using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

// ---------------------------------------------------------------------------
// 1. Build host with DI
// ---------------------------------------------------------------------------
var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<Notepad>();
builder.Services.AddSingleton<ResearchTools>();

builder.Logging.SetMinimumLevel(LogLevel.Warning);

var host = builder.Build();

// ---------------------------------------------------------------------------
// 2. Resolve services and configure agent
// ---------------------------------------------------------------------------
var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient, new()
{
    Instructions = """
        You are a research assistant. When given a topic:
        1. Use the WebSearch tool multiple times with different queries to gather information.
        2. Use the SaveNote tool to record each key finding as a separate note.
        3. After gathering enough information (at least 3 searches), use the GetNotes tool
           to review all your notes, then provide a comprehensive summary.
        Always cite where you found information. Be thorough but concise.
        """,
    DefaultChatOptions = new()
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [
            AIFunctionFactory.Create(researchTools.WebSearch),
            AIFunctionFactory.Create(researchTools.SaveNote),
            AIFunctionFactory.Create(researchTools.GetNotes),
        ],
    },
});

// ---------------------------------------------------------------------------
// 3. Run the research loop
// ---------------------------------------------------------------------------
Console.WriteLine("🔬 Research Agent");
Console.WriteLine(new string('─', 50));

Console.Write("Enter a research topic (or press Enter for default): ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
    topic = "Recent advances in quantum computing";

Console.WriteLine($"\n📚 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions { MaximumIterations = 15 };

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n");
Console.WriteLine(new string('─', 50));

var notepad = host.Services.GetRequiredService<Notepad>();
Console.WriteLine($"📝 Total notes saved: {notepad.Count}");
Console.WriteLine("✅ Research complete.");

// ---------------------------------------------------------------------------
// 4. Tool definitions
// ---------------------------------------------------------------------------

/// <summary>Stores research notes in memory.</summary>
sealed class Notepad
{
    private readonly List<string> _notes = [];
    private readonly Lock _lock = new();

    public int Count { get { lock (_lock) return _notes.Count; } }

    public void Add(string note)
    {
        lock (_lock) _notes.Add(note);
    }

    public IReadOnlyList<string> GetAll()
    {
        lock (_lock) return [.. _notes];
    }
}

/// <summary>Tools exposed to the agent for research workflows.</summary>
sealed class ResearchTools(Notepad notepad)
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a summary of search results.")]
    public async Task<string> WebSearch(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        try
        {
            // Uses the DuckDuckGo Instant Answer API (no key required)
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract / main answer
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"[{abstractSource}] {abstractText}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var t = text.GetString();
                        if (!string.IsNullOrWhiteSpace(t))
                            results.Add($"- {t}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record key findings from your searches.")]
    public string SaveNote(
        [Description("The note content to save")] string content,
        [Description("The source or context for this note")] string source)
    {
        notepad.Add($"[{source}] {content}");
        Console.WriteLine($"  📝 Note saved ({notepad.Count} total)");
        return $"Note saved. You now have {notepad.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to review before writing a summary.")]
    public string GetNotes()
    {
        var notes = notepad.GetAll();
        if (notes.Count == 0)
            return "No notes saved yet. Use SaveNote to record findings first.";

        Console.WriteLine($"  📖 Reviewing {notes.Count} notes");
        return string.Join("\n\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

